"""Todo.txt record parsing shared by command implementations."""
from __future__ import annotations
from dataclasses import dataclass, field
from datetime import date
import re

_WORD = re.compile(r"\S+")
_VALID_DATE = re.compile(r"\d{4}-\d{2}-\d{2}\Z")
_TAG = re.compile(r"^([\w!.-]+):(\S*)$")

@dataclass
class Todo:
    id: int
    raw: str
    subject: str
    done: bool = False
    priority: str | None = None
    created: str | None = None
    completed: str | None = None
    project: list[str] = field(default_factory=list)
    context: list[str] = field(default_factory=list)
    hashtag: list[str] = field(default_factory=list)
    tags: dict[str, list[str]] = field(default_factory=dict)

    @property
    def due(self): return self.first_tag('due')
    @property
    def threshold(self): return self.first_tag('t')
    @property
    def rec(self): return self.first_tag('rec')
    @property
    def time(self): return self.first_tag('time')
    @property
    def hidden(self): return bool(self.first_tag('hidden'))

    def first_tag(self, name):
        values=self.tags.get(name, [])
        return values[0] if values else None

def _date(token):
    if not _VALID_DATE.fullmatch(token): return False
    try: date.fromisoformat(token); return True
    except ValueError: return False

def parse_todo(line: str, id: int = 1) -> Todo:
    """Parse one todo.txt line. Invalid date-like fields remain in subject."""
    raw=line.rstrip("\r\n")
    words=raw.split()
    done=False; completed=None; priority=None; created=None
    if words and words[0].lower()=='x':
        done=True; words.pop(0)
    if words and re.fullmatch(r"\([A-Za-z]\)", words[0]):
        priority=words.pop(0)[1].upper()
    if words and _date(words[0]): created=words.pop(0)
    projects=[]; contexts=[]; hashtags=[]; tags={}
    for word in words:
        if word.startswith('+') and len(word)>1:
            projects.append(word[1:]); continue
        if word.startswith('@') and len(word)>1:
            contexts.append(word[1:]); continue
        if word.startswith('#') and len(word)>1:
            hashtags.append(word[1:]); continue
        m=_TAG.fullmatch(word)
        if m and m.group(1) not in ('due','t','created','completed') or m and m.group(1) in ('due','t','created','completed') and _date(m.group(2)):
            tags.setdefault(m.group(1),[]).append(m.group(2)); continue
    if done and tags.get('completed'):
        completed=tags['completed'][0]
    # TTDL's subject is the full remainder, including inline tags. Consumers
    # that render a cleaned subject can remove values represented in columns.
    return Todo(id,raw,' '.join(words),done,priority,created,completed,projects,contexts,hashtags,tags)

def parse_lines(text: str) -> list[Todo]:
    return [parse_todo(line,i) for i,line in enumerate(text.splitlines(),1)]
"""Helpers for the append, prepend and postpone TTDL commands.

These functions operate on todo.txt records and intentionally keep formatting
and command line parsing in the caller.
"""
import calendar
import datetime as _dt
import re
from datetime import date
from dates import parse_date_expression

_DURATION = re.compile(r"^(\d+)([dwmy])$", re.I)
_DATE = re.compile(r"\b(due|t):([0-9]{4}-[0-9]{2}-[0-9]{2})")


def _add_months(d, n):
    m = d.month - 1 + n
    y, m = d.year + m // 12, m % 12 + 1
    last = calendar.monthrange(y, m)[1]
    # Preserve end-of-month recurrence/postponement behavior.
    day = last if d.day == calendar.monthrange(d.year, d.month)[1] else min(d.day, last)
    return d.replace(year=y, month=m, day=day)


def shift_date(value, duration):
    """Shift an ISO date by a TTDL duration such as 5d, 2w, 1m or 1y."""
    m = _DURATION.fullmatch(duration.strip())
    if not m:
        raise ValueError("invalid duration")
    n, unit = int(m.group(1)), m.group(2).lower()
    d = _dt.date.fromisoformat(value)
    if unit == "d":
        d += _dt.timedelta(days=n)
    elif unit == "w":
        d += _dt.timedelta(weeks=n)
    else:
        d = _add_months(d, n * (12 if unit == "y" else 1))
    return d.isoformat()


def append_subject(subject, text, prepend=False):
    """Join a text fragment onto a subject, rejecting tag-only fragments."""
    words = text.split()
    if not words or all(w.startswith(("+", "@")) for w in words):
        raise ValueError("Subject is empty")
    joined = (text.strip() + " " + subject.strip()).strip() if prepend else (subject.strip() + " " + text.strip()).strip()
    # The normal parser treats date tags added through append/prepend exactly
    # like date tags on a newly added todo.
    tags = {key.lower(): val for key, val in re.findall(r"\b([\w-]+):([^\s]+)", joined)}
    def norm(m):
        key, value = m.groups()
        try:
            return key + ":" + parse_date_expression(value, today=date.today(), tags=tags).isoformat()
        except ValueError:
            return m.group(0)
    return re.sub(r"\b(due|t):([^\s]+)", norm, joined)


def postpone_subject(subject, duration, update_threshold=False):
    """Move due date, and optionally threshold, relative to the existing date."""
    def repl(match):
        key, date = match.groups()
        if key == "due" or (update_threshold and key == "t"):
            return key + ":" + shift_date(date, duration)
        return match.group(0)
    if not re.search(r"\bdue:[0-9]{4}-[0-9]{2}-[0-9]{2}", subject):
        return None
    return _DATE.sub(repl, subject)

"""Date expression support used by TTDL's add/edit date setters.

The command accepts a base date (or another todo tag) followed by any number
of +/- durations, for example ``t+1w-2d``.  This module deliberately has no
CLI or file dependencies so it can be shared by the parser and mutations.
"""
from __future__ import annotations

import calendar
import re
from datetime import date, timedelta
from typing import Mapping, Optional

_WEEKDAYS = {
    "mo": 0, "mon": 0, "monday": 0,
    "tu": 1, "tue": 1, "tuesday": 1,
    "we": 2, "wed": 2, "wednesday": 2,
    "th": 3, "thu": 3, "thursday": 3,
    "fr": 4, "fri": 4, "friday": 4,
    "sa": 5, "sat": 5, "saturday": 5,
    "su": 6, "sun": 6, "sunday": 6,
}
_MONTHS = {name.lower(): i for i, names in enumerate((
    ("jan", "january"), ("feb", "february"), ("mar", "march"),
    ("apr", "april"), ("may",), ("jun", "june"),
    ("jul", "july"), ("aug", "august"), ("sep", "september"),
    ("oct", "october"), ("nov", "november"), ("dec", "december"),
), 1) for name in names}


def _month_add(d: date, n: int) -> date:
    last = d.day == calendar.monthrange(d.year, d.month)[1]
    serial = d.year * 12 + d.month - 1 + n
    year, month0 = divmod(serial, 12)
    month = month0 + 1
    day = calendar.monthrange(year, month)[1] if last else min(d.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def _base_date(value: str, today: date) -> Optional[date]:
    v = value.strip().lower()
    try:
        return date.fromisoformat(v)
    except ValueError:
        pass
    if v in ("today", "now"):
        return today
    if v in ("tm", "tmr", "tomorrow"):
        return today + timedelta(days=1)
    if v in _WEEKDAYS:
        delta = (_WEEKDAYS[v] - today.weekday()) % 7 or 7
        return today + timedelta(days=delta)
    if v in _MONTHS:
        month = _MONTHS[v]
        year = today.year + (month <= today.month)
        return date(year, month, 1)
    # Human readable day of month, and month-day, always in the future.
    if re.fullmatch(r"\d{1,2}", v):
        day = int(v)
        if not 1 <= day <= 31:
            return None
        month, year = today.month, today.year
        if day < today.day:
            month += 1
            if month == 13:
                month, year = 1, year + 1
        return date(year, month, min(day, calendar.monthrange(year, month)[1]))
    m = re.fullmatch(r"(\d{1,2})-(\d{1,2})", v)
    if m:
        month, day = map(int, m.groups())
        if not 1 <= month <= 12 or not 1 <= day <= 31:
            return None
        year = today.year + (date(today.year, month, min(day, calendar.monthrange(today.year, month)[1])) < today)
        return date(year, month, min(day, calendar.monthrange(year, month)[1]))
    # Relative human dates such as 2w1d or 3m.
    if re.fullmatch(r"\d+[dwmy]?(?:\d+[dwmy]?)*", v):
        d = today
        for num, unit in re.findall(r"(\d+)([dwmy]?)", v):
            n = int(num)
            if unit == "w": d += timedelta(days=7*n)
            elif unit == "m": d = _month_add(d, n)
            elif unit == "y": d = _month_add(d, 12*n)
            else: d += timedelta(days=n)
        return d
    return None


def parse_date_expression(expression: str, *, today: Optional[date] = None,
                          tags: Optional[Mapping[str, str]] = None,
                          max_depth: int = 64) -> date:
    """Resolve an add/edit date expression to a date.

    ``tags`` maps tag names (for example ``t`` or ``when``) to their raw
    values. Unknown bases, invalid dates, and cycles raise ``ValueError``.
    """
    today = today or date.today()
    tags = tags or {}
    expr = expression.strip()
    # Split after the base: '-' also appears inside ISO dates and month-day.
    # A plus can only be an operation, while a minus operation must be
    # recognized as a signed duration (not as a date separator).
    first_plus = expr.find("+")
    if first_plus >= 0:
        start = first_plus
    else:
        # For minus-only expressions, first establish whether the whole
        # string is a valid base; otherwise match the trailing duration chain.
        lowered_tags = {str(k).lower(): str(v) for k, v in tags.items()}
        if _base_date(expr, today) is not None:
            start = len(expr)
        else:
            candidates = list(re.finditer(r"-(?=\d+[dwmy]?(?:-|$))", expr, re.I))
            start = len(expr)
            # Work right-to-left so an ISO date or month-day base stays whole.
            for candidate in reversed(candidates):
                prefix = expr[:candidate.start()]
                if _base_date(prefix, today) is not None or prefix.lower() in lowered_tags:
                    start = candidate.start()
                    break
    base = expr[:start] if start < len(expr) else expr
    ops = list(re.compile(r"([+-])(\d+)([dwmy]?)", re.I).finditer(expr, start))
    cursor = start
    for m in ops:
        if m.start() != cursor:
            raise ValueError("invalid date expression")
        cursor = m.end()
    if cursor != len(expr):
        raise ValueError("invalid date expression")

    def resolve(raw: str, seen: frozenset[str], depth: int) -> date:
        if depth > max_depth:
            raise ValueError("recursion limit")
        d = _base_date(raw, today)
        if d is None:
            key = raw.strip().lower()
            normalized_tags = {str(k).lower(): str(v) for k, v in tags.items()}
            if key in seen or key not in normalized_tags:
                raise ValueError("invalid date expression")
            d = resolve(normalized_tags[key], seen | {key}, depth + 1)
        return d

    result = resolve(base, frozenset(), 0)
    for m in ops:
        amount = int(m.group(2)) * (1 if m.group(1) == "+" else -1)
        unit = m.group(3).lower()
        if unit == "w": result += timedelta(days=amount * 7)
        elif unit == "m": result = _month_add(result, amount)
        elif unit == "y": result = _month_add(result, amount * 12)
        else: result += timedelta(days=amount)
    return result


# Convenient shorter alias for callers.
parse_date = parse_date_expression

