"""Todo metadata edit helpers for the CLI dispatcher."""
from __future__ import annotations
import re


def _options(args):
    opts={}
    i=0
    while i<len(args):
        a=args[i]
        if a.startswith('--'):
            if '=' in a: k,v=a[2:].split('=',1)
            elif i+1<len(args) and not args[i+1].startswith('-'):
                k,v=a[2:],args[i+1]; i+=1
            else: k,v=a[2:],''
            opts[k]=v
        i+=1
    return opts


def _csv(value):
    return [x.strip() for x in value.split(',') if x.strip()]


def _pairs(value, sep=':'):
    out=[]
    for part in _csv(value):
        if sep in part:
            a,b=part.split(sep,1); out.append((a,b))
    return out


def edit_record(line, args):
    """Apply metadata set/delete/replace flags while preserving todo fields."""
    from parser import parse_todo
    t=parse_todo(line)
    opts=_options(args)
    words=t.subject.split()

    def values(opt, marker=''):
        return [x[len(marker):] if marker and x.startswith(marker) else x for x in _csv(opts.get(opt,''))]

    # Priority is represented before the subject, with the created date kept
    # after priority. TTDL uses Z as the lowest priority for an unset task.
    pri=t.priority
    if 'set-pri' in opts:
        v=opts['set-pri'].upper()
        if v=='NONE': pri=None
        elif v=='+': pri=chr(max(ord('A'),ord(pri)-1)) if pri else None
        elif v=='-': pri=chr(min(ord('Z'),ord(pri)+1)) if pri else None
        elif len(v)==1 and 'A'<=v<='Z': pri=v

    # Set project/context lists add missing values without duplication.
    for opt,marker in (('set-proj','+'),('set-ctx','@')):
        if opt in opts:
            existing={w[1:] for w in words if w.startswith(marker)}
            for v in values(opt,marker):
                if v not in existing: words.append(marker+v); existing.add(v)

    for opt in ('set-tag','set-time','set-rec'):
        if opt not in opts: continue
        if opt=='set-tag': pairs=_pairs(opts[opt],':')
        elif opt=='set-time': pairs=[('time',opts[opt])]
        else: pairs=[('rec',opts[opt])]
        for key,val in pairs:
            replaced=False; next_words=[]
            for w in words:
                if ':' in w and w.split(':',1)[0]==key:
                    if val.lower()!='none' and not replaced:
                        next_words.append(f'{key}:{val}'); replaced=True
                else: next_words.append(w)
            if val.lower()!='none' and not replaced: next_words.append(f'{key}:{val}')
            words=next_words

    for opt in ('set-hashtag',):
        if opt in opts:
            for val in values(opt,'#'):
                token='#'+val
                if token not in words: words.append(token)
    # The CLI applies all set operations before delete operations, then
    # replacements. This matters when the same key appears in several flags.
    for opt,marker in (('del-proj','+'),('del-ctx','@')):
        if opt in opts:
            denied=set(values(opt,marker)); words=[w for w in words if not (w.startswith(marker) and w[1:] in denied)]
    for opt,marker in (('del-tag',''),('del-hashtag','#')):
        if opt in opts:
            denied=set(values(opt,marker))
            if opt=='del-tag': words=[w for w in words if not (':' in w and w.split(':',1)[0] in denied)]
            else: words=[w for w in words if not (w.startswith('#') and w[1:] in denied)]
    for opt,marker in (('repl-proj','+'),('repl-ctx','@'),('repl-hashtag','#')):
        if opt not in opts: continue
        sep={'repl-proj':'+','repl-ctx':'@','repl-hashtag':':'}[opt]
        for old,new in _pairs(opts[opt],sep):
            old=old.lstrip(marker); new=new.lstrip(marker)
            for i,w in enumerate(words):
                if w==marker+old: words[i]=marker+new
    subject=' '.join(words)
    prefix=[]
    if t.done:
        prefix.append('x')
        if t.completed: prefix.append(t.completed)
        if pri: prefix.append(f'({pri})')
        if t.created: prefix.append(t.created)
    else:
        if pri: prefix.append(f'({pri})')
        if t.created: prefix.append(t.created)
    return ' '.join(prefix+[subject]).strip()

def _month_add(d: date, n: int) -> date:
    last = d.day == calendar.monthrange(d.year, d.month)[1]
    serial = d.year * 12 + d.month - 1 + n
    year, month0 = divmod(serial, 12)
    month = month0 + 1
    day = calendar.monthrange(year, month)[1] if last else min(d.day, calendar.monthrange(year, month)[1])
    return date(year, month, day)


def _base_date(value: str, today: date) -> Optional[date]:
    v = value.strip().lower()
    try:
        return date.fromisoformat(v)
    except ValueError:
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", v):
            raise ValueError(f"Invalid date [{value}]: input is out of range")
    if v in ("today", "now"):
        return today
    if v in ("tm", "tmr", "tomorrow"):
        return today + timedelta(days=1)
    if v in _WEEKDAYS:
        delta = (_WEEKDAYS[v] - today.weekday()) % 7 or 7
        return today + timedelta(days=delta)
    if v in _MONTHS:
        month = _MONTHS[v]
        year = today.year + (month <= today.month)
        return date(year, month, 1)
    # Human readable day of month, and month-day, always in the future.
    if re.fullmatch(r"\d{1,2}", v):
        day = int(v)
        if not 1 <= day <= 31:
            return None
        month, year = today.month, today.year
        if day < today.day:
            month += 1
            if month == 13:
                month, year = 1, year + 1
        return date(year, month, min(day, calendar.monthrange(year, month)[1]))
    m = re.fullmatch(r"(\d{1,2})-(\d{1,2})", v)
    if m:
        month, day = map(int, m.groups())
        if not 1 <= month <= 12 or not 1 <= day <= 31:
            return None
        year = today.year + (date(today.year, month, min(day, calendar.monthrange(today.year, month)[1])) < today)
        return date(year, month, min(day, calendar.monthrange(year, month)[1]))
    # Relative human dates such as 2w1d or 3m.
    if re.fullmatch(r"\d+[dwmy](?:\d+[dwmy])*", v):
        d = today
        for num, unit in re.findall(r"(\d+)([dwmy]?)", v):
            n = int(num)
            if unit == "w": d += timedelta(days=7*n)
            elif unit == "m": d = _month_add(d, n)
            elif unit == "y": d = _month_add(d, 12*n)
            else: d += timedelta(days=n)
        return d
    return None


def parse_date_expression(expression: str, *, today: Optional[date] = None,
                          tags: Optional[Mapping[str, str]] = None,
                          max_depth: int = 64) -> date:
    """Resolve an add/edit date expression to a date.

    ``tags`` maps tag names (for example ``t`` or ``when``) to their raw
    values. Unknown bases, invalid dates, and cycles raise ``ValueError``.
    """
    today = today or date.today()
    tags = tags or {}
    normalized_tags = {
        str(k).lower(): str(v[0] if isinstance(v, (list, tuple)) and v else v)
        for k, v in tags.items()
    }
    expr = expression.strip()
    # Split after the base: '-' also appears inside ISO dates and month-day.
    # A plus can only be an operation, while a minus operation must be
    # recognized as a signed duration (not as a date separator).
    first_plus = expr.find("+")
    if first_plus >= 0:
        start = first_plus
    else:
        # For minus-only expressions, first establish whether the whole
        # string is a valid base; otherwise match the trailing duration chain.
        if _base_date(expr, today) is not None:
            start = len(expr)
        else:
            candidates = list(re.finditer(r"-(?=\d+[dwmy]?(?:-|$))", expr, re.I))
            start = len(expr)
            # Work right-to-left so an ISO date or month-day base stays whole.
            for candidate in reversed(candidates):
                prefix = expr[:candidate.start()]
                if _base_date(prefix, today) is not None or prefix.lower() in normalized_tags:
                    start = candidate.start()
                    break
    base = expr[:start] if start < len(expr) else expr
    ops = list(re.compile(r"([+-])(\d+)([dwmy]?)", re.I).finditer(expr, start))
    cursor = start
    for m in ops:
        if m.start() != cursor:
            raise ValueError("invalid date expression")
        cursor = m.end()
    if cursor != len(expr):
        raise ValueError("invalid date expression")

    def resolve(raw: str, seen: frozenset[str], depth: int) -> date:
        if depth > max_depth:
            raise ValueError("recursion limit")
        d = _base_date(raw, today)
        if d is None:
            key = raw.strip().lower()
            if key in seen or key not in normalized_tags:
                raise ValueError("Recursion stack overflow" if key in seen else f"invalid date '{raw}'")
            d = resolve(normalized_tags[key], seen | {key}, depth + 1)
        return d

    try:
        result = resolve(base, frozenset(), 0)
        for m in ops:
            amount = int(m.group(2)) * (1 if m.group(1) == "+" else -1)
            unit = m.group(3).lower()
            if unit == "w": result += timedelta(days=amount * 7)
            if unit == "w": result += timedelta(days=amount * 7)
            elif unit == "m": result = _month_add(result, amount)
            elif unit == "y": result = _month_add(result, amount * 12)
            else: result += timedelta(days=amount)
        return result
    except OverflowError as exc:
        raise ValueError("invalid date expression") from exc
    except ValueError as exc:
        if str(exc) in ("invalid date expression", "recursion limit", "Recursion stack overflow") or str(exc).startswith("Invalid date [") or str(exc).startswith("invalid date '"):
            raise
        raise ValueError("invalid date expression") from exc


def normalize_date_tags(subject: str, *, today: Optional[date] = None) -> str:
    """Resolve ``due:`` and ``t:`` expressions within a todo subject.

    Other tags are available as expression bases and remain unchanged in the
    returned subject. Date tag values are saved as ISO dates.
    """
    today = today or date.today()
    tags: dict[str, str] = {}
    for key, value in re.findall(r"\b([\w!.-]+):(\S+)", subject):
        tags.setdefault(key.lower(), value)
    for field in ("due", "t"):
        if field in tags:
            try:
                tags[field] = parse_date_expression(tags[field], today=today, tags=tags).isoformat()
            except ValueError as exc:
                # TTDL evaluates due before threshold. If due is exactly an
                # alias for t and t references due, due starts from today;
                # threshold then resolves against that newly calculated due.
                if field == "due" and tags[field].strip().lower() == "t" and re.fullmatch(r"due(?:[+-]\d+[dwmy]?)?", tags.get("t", ""), re.I):
                    tags[field] = today.isoformat()
                else:
                    raise exc
    def replace(match: re.Match[str]) -> str:
        key = match.group(1).lower()
        value = tags.get(key)
        if key in ("due", "t") and value is not None:
            return match.group(1) + ":" + value
        return match.group(0)
    return re.sub(r"\b(due|t):(\S+)", replace, subject, flags=re.I)


def set_date_tag(subject: str, field: str, expression: str, *, today: Optional[date] = None) -> str:
    """Set or remove a due/threshold date in a subject, resolving dependencies."""
    field = "t" if field.lower() in ("t", "threshold") else field.lower()
    if field not in ("due", "t"):
        raise ValueError("unsupported date field")
    if expression.strip().lower() == "none":
        return re.sub(rf"\b{re.escape(field)}:\S+", "", subject).strip()
    tags: dict[str, str] = {}
    for key, value in re.findall(r"\b([\w!.-]+):(\S+)", subject):
        tags.setdefault(key.lower(), value)
    resolved = parse_date_expression(expression, today=today, tags=tags).isoformat()
    pattern = re.compile(rf"\b{re.escape(field)}:\S+")
    if pattern.search(subject):
        return pattern.sub(field + ":" + resolved, subject, count=1)
    return (subject.rstrip() + " " + field + ":" + resolved).strip()


# Convenient shorter alias for callers.
parse_date = parse_date_expression

