"""Helpers for TTDL's persistent time tracking tags."""
import re
import time


def get_tag(subject, name):
    m = re.search(r"(?:^|\s)" + re.escape(name) + r":([^\s]*)", subject)
    return m.group(1) if m else None


def set_tag(subject, name, value):
    pat = r"(?:^|\s)" + re.escape(name) + r":[^\s]*"
    if re.search(pat, subject):
        return re.sub(pat, lambda m: (" " if m.group(0).startswith(" ") else "") + name + ":" + str(value), subject, count=1)
    return (subject + " " if subject else "") + name + ":" + str(value)


def start_subject(subject, now=None):
    """Return (updated_subject, changed); a running timer cannot be restarted."""
    now = int(time.time() if now is None else now)
    timer = get_tag(subject, "tmr")
    if timer not in (None, "", "off"):
        # A malformed non-empty timer tag is left alone by the CLI too.
        try:
            int(timer)
        except ValueError:
            return subject, False
        return subject, False
    return set_tag(subject, "tmr", now), True


def stop_subject(subject, now=None):
    """Return (updated_subject, changed); spent is recorded as elapsed seconds."""
    now = int(time.time() if now is None else now)
    timer = get_tag(subject, "tmr")
    if timer in (None, "", "off"):
        return subject, False
    try:
        seconds = max(0, now - int(timer))
    except ValueError:
        return subject, False
    subject = set_tag(subject, "tmr", "off")
    subject = set_tag(subject, "spent", seconds)
    return subject, True
